          <i class="fas fa-times-circle" aria-hidden="true"></i>
        </button>
        <button v-if="!embedded" type="button" class="sp-esc" aria-label="Close palette" @click="close">
          <span class="sp-close-desktop">esc</span>
          <MobileMenuGlyph class="sp-close-mobile" :open="!mobileClosing" />
