            <button type="button" class="sp-mobile-mode-option" :class="{ active: mode === 'view' }" role="menuitem" :disabled="viewBusy" @click="selectMobileMode('view')">
              <i class="far fa-file-alt" aria-hidden="true"></i>
              <span><strong><AiViewTerm /></strong><small>Compose a reading path</small></span>
              <span class="sp-mobile-mode-dot" aria-hidden="true"></span>
            </button>
            <button type="button" class="sp-mobile-mode-option" :class="{ active: mode === 'search' }" role="menuitem" :disabled="viewBusy" @click="selectMobileMode('search')">
              <i class="fas fa-search" aria-hidden="true"></i>
              <span><strong>Search</strong><small>Find original material</small></span>
              <span class="sp-mobile-mode-dot" aria-hidden="true"></span>
            </button>
            <button type="button" class="sp-mobile-mode-option" :class="{ active: mode === 'map' }" role="menuitem" :disabled="viewBusy" @click="selectMobileMode('map')">
              <i class="far fa-compass" aria-hidden="true"></i>
              <span><strong>Map</strong><small>Explore ideas spatially</small></span>
              <span class="sp-mobile-mode-dot" aria-hidden="true"></span>
            </button>
          </div>
        </transition>
        <span v-if="semStatus" class="sp-mode-status">{{ semStatus }}</span>
        <div v-if="mode === 'map'" class="sp-projection-toggle" aria-label="Map projection">
          <button
            type="button"
            class="sp-projection"
            :class="{ active: mapProjection === '2d' }"
            :aria-pressed="(mapProjection === '2d').toString()"
            @click="setMapProjection('2d')"
          >2D</button>
          <button
            type="button"
            class="sp-projection"
            :class="{ active: mapProjection === '3d' }"
            :aria-pressed="(mapProjection === '3d').toString()"
            @click="setMapProjection('3d')"
          >3D</button>
        </div>
      </div>

      <div ref="results" class="sp-results" :inert="embeddedDemoLocked" @pointerdown="mobileModeMenuOpen = false">
        <div v-if="mode === 'map'" class="sp-map">
          <EmbeddingMap
            ref="paletteMap"
            compact
            fit-stage
            :initial-view-mode="mapProjection"
            :show-controls="false"
            :show-view-toggle="false"
            :show-caption="false"
            :show-hits="false"
            :lock-pan-on-touch="false"
            @navigate="close"
          />
        </div>

        <template v-else-if="mode === 'search'">
          <template v-if="query.trim() && groups.length">
            <div v-for="g in groups" :key="g.page" class="sp-group">
              <div class="sp-group-label">{{ g.page }}</div>
              <button
                v-for="r in g.items"
                :key="r.flatIndex"
                class="sp-result"
                :class="{ active: r.flatIndex === activeIndex }"
                :ref="el => setRowRef(el, r.flatIndex)"
                @mousemove="activeIndex = r.flatIndex"
                @click="openResult(r, 'click')"
              >
                <span class="sp-result-title" v-html="r.titleHtml"></span>
                <span v-if="r.snippetHtml" class="sp-result-snippet" v-html="r.snippetHtml"></span>
              </button>
            </div>
          </template>

          <div v-else-if="query.trim() && semBusy" class="sp-empty">
            {{ semLoading ? 'Getting search ready…' : 'Searching…' }}
          </div>

          <div v-else-if="query.trim()" class="sp-empty">
            No matches for &ldquo;{{ query.trim() }}&rdquo;.
          </div>

          <div v-else class="sp-group">
            <div class="sp-group-label">Jump to</div>
            <button
              v-for="s in suggestions"
              :key="s.route"
              class="sp-result sp-jump"
              @click="go(s.route, '')"
            >
              <span class="sp-result-title">{{ s.label }}</span>
              <span class="sp-jump-arrow" aria-hidden="true">&rarr;</span>
            </button>
          </div>
        </template>

        <div v-else-if="mode === 'view'" class="sp-view-compose">
          <div v-if="!askReady" class="sp-empty">
            View is temporarily unavailable. Please try again later.
          </div>
          <ViewComposeProgress v-else-if="viewBusy" :started-at="viewStartedAt" />
          <ViewComposeProgress
            v-else-if="externalComposeActive"
            :started-at="externalComposeStartedAt"
          />
          <div v-else-if="viewError" class="sp-empty sp-view-error" role="alert">{{ viewError }}</div>
          <div v-else class="sp-view-start">
            <p class="sp-view-note"><AiViewTerm /> connects material from across Henry&rsquo;s site around your question and keeps every original source within reach.</p>
            <div class="sp-view-heading-row">
              <span class="sp-view-examples-label">Recently shared</span>
              <button type="button" class="sp-view-public-link" @click="openPublicViews">
                <span>Explore more</span>
                <ArrowUpRightIcon />
              </button>
            </div>
            <div v-if="recentSharedViews.length" class="sp-view-examples" aria-label="Recently shared Views">
              <button
                v-for="view in recentSharedViews"
                :key="view.id"
                type="button"
                @click="openSharedView(view.id)"
              >
                <span class="sp-view-example-copy">
                  <strong>{{ view.title }}</strong>
                  <small>&ldquo;{{ view.question }}&rdquo;</small>
                </span>
                <span class="sp-view-example-arrow" aria-hidden="true">→</span>
              </button>
            </div>
            <div
              v-else-if="recentSharedViewsLoading"
              class="sp-view-examples sp-view-examples-loading"
              role="status"
              aria-label="Loading recently shared Views"
            >
              <span v-for="index in 3" :key="index" class="sp-view-skeleton-row" aria-hidden="true">
                <span class="sp-view-skeleton-copy">
                  <span class="sp-view-skeleton-line sp-view-skeleton-title"></span>
                  <span class="sp-view-skeleton-line sp-view-skeleton-question"></span>
                </span>
                <span class="sp-view-skeleton-mark"></span>
              </span>
            </div>
          </div>
        </div>

        <div v-else class="sp-ask">
          <div v-if="!askReady" class="sp-empty">
            Ask is temporarily unavailable. Please try again later.
          </div>
          <template v-else>
            <ViewComposeProgress v-if="viewBusy" :started-at="viewStartedAt" />
            <template v-else-if="answerText">
              <transition
                appear
                @before-enter="beforeAnswerEnter"
                @enter="enterAnswer"
                @leave="leaveAnswer"
              >
                <p class="sp-ask-answer" v-html="answerHtml"></p>
              </transition>
              <AskAnswerAudio v-if="!askBusy" :text="answerText" />
              <AskActions
                v-if="askActionsList.length && answerText && !askBusy && !viewBusy"
                :actions="askActionsList"
                surface="palette"
              />
            </template>
            <TextShimmerWave
              v-else-if="askBusy"
              :children="askStatus || 'Thinking…'"
              as="div"
              class-name="sp-empty sp-thinking"
            />
            <div v-else-if="viewError" class="sp-empty sp-view-error" role="alert">{{ viewError }}</div>
            <div v-else-if="askError" class="sp-empty" role="alert">{{ askErrorText }}</div>
            <div v-else class="sp-empty sp-ask-empty">
              <button
                type="button"
                class="sp-ask-sample"
                :class="{ visible: sampleVisible }"
                @click="useCurrentSample"
              >{{ currentSamplePrompt }}</button>
            </div>

            <AskViewOffer
              v-if="viewOfferVisible && answerText && !askBusy && !askError && !viewBusy"
              :title="canReturnToView ? 'Your composed view is ready' : viewOffer.title"
              :description="canReturnToView ? 'Continue through the sources and connections shaped around your question.' : viewOffer.description"
              :label="canReturnToView ? 'Return to the view' : 'Explore the story'"
              @explore="buildViewFromCurrent"
            />

            <div v-if="citedSources.length && !askBusy && !viewBusy" class="sp-ask-sources">
              <div class="sp-group-label">Sources</div>
              <transition-group
                appear
                tag="div"
                class="sp-ask-source-list"
                @before-enter="beforeChipEnter"
                @enter="enterChip"
                @leave="leaveChip"
              >
                <button
                  v-for="s in citedSources"
                  :key="`${s.route}#${s.anchor || ''}`"
                  :data-source-key="`${s.route}#${s.anchor || ''}`"
                  class="sp-ask-source ask-source-link"
                  :class="{ 'is-previewed': hoveredSourceId === `${s.route}#${s.anchor || ''}` }"
                  @mouseenter="hoveredSourceId = `${s.route}#${s.anchor || ''}`"
                  @mouseleave="hoveredSourceId = null"
                  @focus="hoveredSourceId = `${s.route}#${s.anchor || ''}`"
                  @blur="hoveredSourceId = null"
                  @click="openAskSource(s)"
                >{{ s.page }} › {{ s.displayTitle }}</button>
              </transition-group>
            </div>

            <div v-if="askFollowUpQuestions.length && answerText && !askBusy && !viewBusy" class="sp-ask-followups">
              <div class="sp-group-label">Keep exploring</div>
              <div class="sp-ask-followup-list">
                <button
                  v-for="q in askFollowUpQuestions"
                  :key="q"
                  type="button"
                  class="sp-ask-followup ask-followup-chip"
                  @click="askFollowUp(q)"
                >{{ q }}</button>
              </div>
            </div>
          </template>
        </div>
      </div>

      <DemoInteractionGate
        v-if="embeddedDemoEnabled"
        :active="embeddedDemoActive"
        :label="embeddedDemoLabel"
        @activate="activateEmbeddedDemo"
        @deactivate="deactivateEmbeddedDemo"
      />

      <!-- Hover preview floats above the panel content (and never pushes the
           layout): it is positioned against the panel and follows the hovered
           source chip, recomputed on results scroll. -->
      <transition name="sp-preview-fade">
        <div
          v-if="askSourcePreview"
          :key="askSourcePreview.id"
          class="sp-ask-preview"
          :style="previewStyle"
        >
          <span class="sp-ask-preview-kicker">{{ askSourcePreview.page }} › {{ askSourcePreview.title }}</span>
          <p class="sp-ask-preview-text">{{ askSourcePreview.snippet }}</p>
        </div>
      </transition>

      <div v-if="!embedded" class="sp-foot">
        <span><kbd>⌥</kbd> mode</span>
        <span><kbd>&crarr;</kbd> {{ mode === 'ask' ? 'ask' : (mode === 'view' ? 'compose' : (mode === 'map' ? 'place' : 'open')) }}</span>
        <span v-if="mode === 'search'"><kbd>&uarr;</kbd><kbd>&darr;</kbd> move</span>
        <span><kbd>esc</kbd> close</span>
      </div>
    </div>
  </div>
</template>

<script>
import AskViewOffer from './ui/AskViewOffer.vue';
import { prepareAskSourceReturn, consumeAskSourceDeparture } from '../utils/askReturn.js';
import Fuse from 'fuse.js';
import EmbeddingMap from './EmbeddingMap.vue';
import ViewComposeProgress from './view/ViewComposeProgress.vue';
import TextShimmerWave from './ui/TextShimmerWave.vue';
import AskAnswerAudio from './ui/AskAnswerAudio.vue';
import AskActions from './ui/AskActions.vue';
import AiViewTerm from './ui/AiViewTerm.vue';
import AiAskTerm from './ui/AiAskTerm.vue';
import MobileMenuGlyph from './ui/MobileMenuGlyph.vue';
import DemoInteractionGate from './ui/DemoInteractionGate.vue';
import { animate } from 'motion';
import { ensureReady, semanticRank } from '../utils/semanticSearch';
import { askConfigured, askStream, askErrorMessage } from '../utils/askSite';
import { ASK_SAMPLE_PROMPTS } from '../utils/askPrompts';
import {
  allAskContexts,
  diversifyAskWritingContexts,
  askAnswerFollowUps,
  askResponseIsComplete,
  citedSourcesFromAnswer,
  cleanAskAnswer,
  cleanAskContextText,
  groundAskFollowUps,
  looksLikeViewBuildRequest,
  sourceDisplayTitle,
  takeRetrievalTrace,
  askViewRouting,
  askViewOffer,
} from '../utils/askRetrieval';
import {
  loadAskSession,
  addAskTurn,
  setAskView,
  setAskOrigin,
  recentAskTurns,
  askSourceIdsInRecent,
  recentDuplicateViewQuestion,
} from '../utils/askSession';
import {
  beginViewCompose,
  cleanViewIntent,
  developViewDelay,
  DEVELOP_VIEW_LABEL,
  DEVELOP_VIEW_ROUTE,
  endViewCompose,
  isDevelopMode,
  isViewComposing,
  requestView,
  viewComposeState,
} from '../utils/viewSite';
import { candidatesForView } from '../utils/viewRetrieval';
import { listPublicViews } from '../utils/viewShareSite';
import { sanitizeViewResponse, validateViewResponse } from '../utils/viewValidation';
import { askActionsForDisplay, renderAskAnswerLinks } from '../utils/askActions';
import { settleScrollToId } from '../utils/anchorLanding';
import {
  logAskClient,
  logEvent,
  logSearch,
  logSearchClick,
  newAskContext,
  newId,
  sessionId,
} from '../utils/askTelemetry';

function collectViewSourceIds(view) {
  const ids = [];
  for (const section of (view && view.sections) || []) {
    for (const block of (section && section.blocks) || []) {
      if (block && block.source_id) ids.push(block.source_id);
      if (block && block.source_ids) ids.push(...block.source_ids);
    }
  }
  return [...new Set(ids)];
}

function isGeneratedViewPath(path) {
  const value = String(path || '');
  return value === '/view' || value.startsWith('/view/');
}

const STOP = new Set([
  'the', 'a', 'an', 'of', 'on', 'in', 'to', 'is', 'are', 'was', 'were', 'be',
  'and', 'or', 'for', 'with', 'at', 'by', 'from', 'as', 'it', 'i', 'my', 'me',
  'this', 'that', 'how', 'what', 'we', 'you', 'they', 'but', 'so', 'if', 'into',
  'about', 'out', 'up', 'over', 'than', 'then', 'has', 'have', 'had', 'do',
]);


export default {
  name: 'SearchPalette',
  emits: ['ai-complete'],
  components: { AskViewOffer, AiAskTerm, AiViewTerm, AskActions, AskAnswerAudio, DemoInteractionGate, EmbeddingMap, MobileMenuGlyph, TextShimmerWave, ViewComposeProgress },
  props: {
    // Rendered inline (no overlay, no scroll lock, no global shortcuts) with
    // a fixed mode and optional prefilled state. Used by the SearchStory page
    // to embed the same search / ask experience the palette provides.
    embedded: {
      type: Boolean,
      default: false,
    },
    fixedMode: {
      type: String,
      default: '',
    },
    initialQuery: {
      type: String,
      default: '',
    },
    initialAnswer: {
      type: String,
      default: '',
    },
    initialSources: {
      type: Array,
      default: () => [],
    },
    initialFollowUps: {
      type: Array,
      default: () => [],
    },
  },
  data() {
    return {
      open: false,
      instantOpen: false,
      query: '',
      savedQueries: { search: '', ask: '', view: '', map: '' },
      mapProjection: '3d',
      items: [],
      fuse: null,
      loaded: false,
      activeIndex: 0,
      rowRefs: {},
      composing: false,
      mode: 'ask',
      semHits: [],
      semLoading: false,
      semQuerying: false,
      semError: '',
      askAnswer: '',
      askSources: [],
      askBusy: false,
      askError: '',
      askStatus: '',
      viewRouting: 'none',
      viewOfferVisible: false,
      viewBusy: false,
      viewStartedAt: 0,
      externalViewJobId: '',
      viewDeparting: false,
      viewError: '',
      recentSharedViews: [],
      recentSharedViewsLoading: false,
      mobileModeMenuOpen: false,
      mobileClosing: false,
      viewSession: null,
      hoveredSourceId: null,
      previewStyle: null,
      groundedFollowUps: null,
      overlayPointerStartedOutside: false,
      overlayPointerEndedOutside: false,
      sampleVisible: true,
      sampleIndex: Math.floor(Math.random() * ASK_SAMPLE_PROMPTS.length),
      samplePrompts: ASK_SAMPLE_PROMPTS,
      embeddedDemoActive: false,
      suggestions: [
        { label: 'About', route: '/about' },
        { label: 'Education', route: '/education' },
        { label: 'Experience', route: '/experience' },
        { label: 'Research', route: '/research' },
        { label: 'Builds', route: '/projects' },
        { label: 'Fragments', route: '/fragments' },
        { label: 'Views', route: '/views' },
        { label: 'CV', route: '/cv' },
      ],
    };
  },
  computed: {
    externalComposeActive() {
      return isViewComposing() && !this.viewBusy;
    },
    externalComposeStartedAt() {
      return viewComposeState.startedAt;
    },
    askInputLocked() {
      return this.viewBusy
        || this.externalComposeActive
        || (this.mode === 'ask' && this.askBusy);
    },
    askErrorText() {
      return askErrorMessage();
    },
    itemsById() {
      const m = {};
      for (const it of this.items) m[it.id] = it;
      return m;
    },
    semBusy() {
      return this.semLoading || this.semQuerying;
    },
    semStatus() {
      if (this.mode === 'map') return '';
      if (this.semError) return 'limited search';
      if (this.semLoading) return 'getting ready…';
      return '';
    },
    paletteLabel() {
      if (this.mode === 'ask') return 'Ask this site';
      if (this.mode === 'view') return 'Compose a View';
      if (this.mode === 'map') return 'Map the site';
      return 'Search the site';
    },
    inputLabel() {
      if (this.mode === 'ask') return 'Ask question';
      if (this.mode === 'view') return 'Describe the View you want';
      if (this.mode === 'map') return 'Map query';
      return 'Search query';
    },
    inputPlaceholder() {
      if (this.mode === 'ask') return 'Ask anything about Henry...';
      if (this.mode === 'view') {
        const phone = typeof window !== 'undefined'
          && window.matchMedia('(max-width: 760px)').matches;
        return phone
          ? 'Understand Henry through...'
          : 'I want to understand Henry through...';
      }
      if (this.mode === 'map') return 'Drop a question into the map...';
      return 'Search the site...';
    },
    askReady() {
      return askConfigured();
    },
    answerText() {
      return cleanAskAnswer(this.askAnswer);
    },
    answerHtml() {
      return renderAskAnswerLinks(this.answerText);
    },
    askActionsList() {
      return askActionsForDisplay(this.askAnswer, this.viewRouting);
    },
    viewOffer() {
      return askViewOffer(this.askAnswer);
    },
    canReturnToView() {
      const viewQuestion = String(this.viewSession?.currentView?.question || '').trim().toLowerCase();
      return !isDevelopMode(this.query)
        && !!viewQuestion
        && viewQuestion === cleanViewIntent(this.query).toLowerCase();
    },
    citedSources() {
      const seen = new Set();
      const out = [];
      const base = citedSourcesFromAnswer(this.askAnswer, this.askSources);
      for (const source of base) {
        const key = `${source.route}#${source.anchor || ''}`;
        if (seen.has(key)) continue;
        seen.add(key);
        out.push({
          ...source,
          displayTitle: this.askDisplayTitle(source),
        });
      }
      return out;
    },
    // Hovering a cited source peeks at its passage without leaving the panel.
    askSourcePreview() {
      if (!this.hoveredSourceId) return null;
      const s = this.citedSources.find(
        (x) => `${x.route}#${x.anchor || ''}` === this.hoveredSourceId,
      );
      if (!s) return null;
      const text = cleanAskContextText(s.body || '').replace(/\s+/g, ' ').trim();
      const snippet = text
        ? (text.length > 220 ? `${text.slice(0, 220).trim()}…` : text)
        : 'Open the passage to read it.';
      return { id: this.hoveredSourceId, page: s.page, title: s.displayTitle, snippet };
    },
    // Only show questions written for this answer and grounded in the site.
    // An empty grounding result intentionally leaves the section hidden.
    askFollowUpQuestions() {
      if (this.askBusy || !this.answerText) return [];
      const rawAiFollowUps = askAnswerFollowUps(this.askAnswer);
      if (this.groundedFollowUps !== null) {
        return this.groundedFollowUps;
      }
      return rawAiFollowUps;
    },
    currentSamplePrompt() {
      return this.samplePrompts[this.sampleIndex] || '';
