    this._lastAskEventId = null;
    this._spAnims = new Set();
    this._viewReturnSnapshot = null;
    this._viewRestoreTimers = [];

    if (this.embedded) {
      // Inline mode: stay open, pin the requested mode, and prefill search or
      // ask state so the embedded panel opens with real content instead of an
      // empty prompt.
      this.open = true;
      if (this.fixedMode && ['search', 'ask', 'view', 'map'].includes(this.fixedMode)) {
        this.mode = this.fixedMode;
      }
      if (this.initialQuery) this.query = this.initialQuery;
      if (this.initialAnswer) this.askAnswer = this.initialAnswer;
      if (this.initialSources && this.initialSources.length) this.askSources = this.initialSources;
      if (this.initialFollowUps && this.initialFollowUps.length) this.groundedFollowUps = this.initialFollowUps;
      this.loadIndex();
      this.warmSemantic();
      if (this.mode === 'search' && this.query.trim()) {
