      this.viewSession = loadAskSession();
      this.instantOpen = via === 'shortcut';
      this.open = true;
      this.viewError = '';
      this.markOpened(via);
      this.sampleVisible = true;
      this.loadIndex();
      this.lockScroll();
      this.warmSemantic();
      if (this.mode === 'view') this.loadRecentSharedViews();
