      this.loadIndex();
      this.lockScroll();
      this.mode = 'ask';
      this.activeIndex = 0;
      this.askAnswer = '';
      this.askSources = [];
      this.askError = '';
      this.viewError = '';
      this.viewOfferVisible = false;
