      await this.$nextTick();
      this.startViewBuild({ askOfferConfirmed: true });
    },
    openView(prefill = '') {
      this.resetMobileClose();
      this.externalViewJobId = '';
      this.viewSession = loadAskSession();
      this.instantOpen = false;
      this.open = true;
      this.mode = 'view';
      this.markOpened(prefill ? 'view_prefill' : 'view_button');
