        mode: this.mode,
        query: this.query,
        savedQueries: { ...this.savedQueries },
        activeIndex: this.activeIndex,
        mapProjection: this.mapProjection,
        pageX: window.scrollX,
        pageY: window.scrollY,
        resultsTop: results ? results.scrollTop : 0,
        resultsLeft: results ? results.scrollLeft : 0,
        panelTop: panel ? panel.scrollTop : 0,
        inputStart: input && typeof input.selectionStart === 'number' ? input.selectionStart : null,
