      this.activeIndex = Number.isInteger(snapshot.activeIndex) ? snapshot.activeIndex : this.activeIndex;
      this.mapProjection = snapshot.mapProjection || this.mapProjection;
      this.instantOpen = true;
      this.open = true;
      window.scrollTo({ left: snapshot.pageX, top: snapshot.pageY, behavior: 'auto' });
      this.lockScroll();

      const restore = () => {
        if (this._viewReturnSnapshot !== snapshot || !this.open) return;
        window.scrollTo({ left: snapshot.pageX, top: snapshot.pageY, behavior: 'auto' });
        const results = this.$refs.results;
        const panel = this.$refs.panel;
        const input = this.$refs.input;
        if (results) {
          results.scrollTop = snapshot.resultsTop;
          results.scrollLeft = snapshot.resultsLeft;
        }
        if (panel) panel.scrollTop = snapshot.panelTop;
        if (input && snapshot.inputStart != null) {
          input.setSelectionRange(snapshot.inputStart, snapshot.inputEnd ?? snapshot.inputStart);
