    async buildViewRequest(signal, seq, completionContext = {}) {
      const rawMessage = this.query.trim();
      const message = cleanViewIntent(rawMessage);
      if (!message) return;
      if (isDevelopMode(rawMessage)) {
        const fakeJob = {
          version: 1,
          jobId: `develop-${Date.now()}-${seq}`,
