          surface: 'palette',
          originRoute: completionContext.originRoute,
          startedAt: Date.now(),
        };
        window.dispatchEvent(new CustomEvent('site-view-job', { detail: fakeJob }));
        await developViewDelay(signal);
        if (signal.aborted || seq !== this._viewSeq) throw new DOMException('Aborted', 'AbortError');
