        // reuse the existing View instead of regenerating it.
        const stayedWithRequest = this.open
          && completionContext.wasOpen
          && this.$route.fullPath === completionContext.originRoute;
        if (stayedWithRequest) {
          await this.enterComposedView();
        } else if (!this.embedded) {
          this.$emit('ai-complete', {
            kind: 'view',
            label: existingView.title || message,
            originRoute: completionContext.originRoute,
            surface: 'palette',
          });
