        ask_offer_confirmed: completionContext.askOfferConfirmed === true,
        event_id: newId(),
        session_id: sessionId(),
        turn_index: this.viewSession && this.viewSession.turns ? this.viewSession.turns.length + 1 : 1,
      };
      this._lastViewEventId = meta.event_id;
      logEvent('view_build_requested', { surface: 'palette', question: message }, meta.event_id);
      const directView = this.mode === 'view';
      const conversation = directView ? [] : recentAskTurns(this.viewSession, 6);
      const sources = await candidatesForView({
        message,
        session: directView ? null : this.viewSession,
        latestMessage: message,
      });
      if (signal.aborted || seq !== this._viewSeq) throw new DOMException('Aborted', 'AbortError');
      const response = await requestView({
        message,
        conversation,
        sources,
        meta,
        signal,
      });
      if (signal.aborted || seq !== this._viewSeq) throw new DOMException('Aborted', 'AbortError');
      const sanitizedResponse = sanitizeViewResponse(response, sources);
      const validation = validateViewResponse(sanitizedResponse, sources);
      if (!validation.ok) throw new Error(validation.error || 'The composed view did not pass validation.');
      if (sanitizedResponse.action === 'answer') {
        this.viewError = String(sanitizedResponse.message || 'Try a question, theme, or perspective that can be explored across Henry’s site.').slice(0, 300);
        logEvent('view_build_declined', {
          surface: 'palette',
          question: message,
          message: this.viewError,
        }, meta.event_id);
        return null;
      }
      if (sanitizedResponse.action !== 'replace_view') {
        throw new Error('The composer did not return a complete view.');
      }

      const normalized = {
        action: sanitizedResponse.action,
        message: response.message || '',
        source_ids: response.source_ids || [],
        view: validation.view || sanitizedResponse.view || null,
      };

      this.viewSession = addAskTurn(this.viewSession, {
        role: 'user',
        text: message,
        source_ids: [],
      });
      const assistantSourceIds = normalized.action === 'replace_view'
        ? collectViewSourceIds(normalized.view)
        : normalized.source_ids;
      this.viewSession = addAskTurn(this.viewSession, {
        role: 'assistant',
        text: normalized.message || (normalized.action === 'replace_view' ? 'View updated.' : ''),
        source_ids: assistantSourceIds,
      });

      if (!normalized.view) throw new Error('Composition returned no view.');
      logEvent('view_build_success', {
        surface: 'palette',
        n_sources: collectViewSourceIds(normalized.view).length,
        n_sections: normalized.view.sections ? normalized.view.sections.length : 0,
      }, meta.event_id);
      this.viewSession = setAskView(this.viewSession, normalized.view);

      const currentRoute = this.$route.fullPath;
      const currentShareId = String(this.$route.params?.shareId || '');
      const previousOrigin = this.viewSession?.origin?.route || '/home';
      const originRoute = isGeneratedViewPath(this.$route.path)
        ? (currentShareId ? currentRoute : previousOrigin)
        : currentRoute;
      this.viewSession = setAskOrigin(this.viewSession, originRoute);
      const stayedWithRequest = this.open
        && completionContext.wasOpen
        && this.$route.fullPath === completionContext.originRoute;
      if (stayedWithRequest) {
